 "content": "def transform(grid):
    """Complete the bounding-box side rails and spans on multi-marker rows."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != background]
    if not colors:
        return [row[:] for row in grid]
    marker = max(colors, key=lambda v: counts[v])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, _ in pts), max(r for r, _ in pts)
    c0, c1 = min(c for _, c in pts), max(c for _, c in pts)
    out = [row[:] for row in grid]
    # Fill the left/right rails through the marker bounding box.
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if out[r][c] == background:
                out[r][c] = 2
    # Rows carrying multiple markers encode horizontal runs across the full
    # bounding-box width; preserve markers and fill only intervening background.
    for r in range(r0, r1 + 1):
        if sum(grid[r][c] == marker for c in range(c0, c1 + 1)) >= 2:
            for c in range(c0, c1 + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
"
}

