 "old_string": "def transform(grid):
    """Complete the bounding-box side rails and spans on multi-marker rows."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != background]
    if not colors:
        return [row[:] for row in grid]
    marker = max(colors, key=lambda v: counts[v])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, _ in pts), max(r for r, _ in pts)
    c0, c1 = min(c for _, c in pts), max(c for _, c in pts)
    out = [row[:] for row in grid]
    # Holes in a contiguous bar are completed. Also complete isolated one-cell
    # gaps between markers in an otherwise non-background row/column; a whole
    # empty stretch is not treated as a line to connect.
    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c] != background:
                continue
            # Fill a one-cell gap in a continuous bar, or a gap between two
            # same-color supports if that row contains at least two markers.
            if grid[r][c - 1] == marker and grid[r][c + 1] == marker:
                out[r][c] = 2
            elif (grid[r][c - 1] == grid[r][c + 1] != background
                  and grid[r][c - 1] == marker
                  and grid[r][c - 1] == grid[r][c + 1]):
                out[r][c] = 2
    for c in range(w):
        for r in range(1, h - 1):
            if grid[r][c] == background and grid[r - 1][c] == marker and grid[r + 1][c] == marker:
                out[r][c] = 2
    return out
